#!/usr/bin/env python3
"""Build a tentative, evidence-grounded proposal; never launch inference."""
from copy import deepcopy
import hashlib
import importlib.util
import json
from pathlib import Path
import re
from build_site import ASSET_COUNTS, e, inline_links, link, p, section, small, table
from site_navigation import project_tabs, review_tabs

ROOT = Path(__file__).resolve().parents[1]
OUT = ROOT/'research/prethinking'
spec = importlib.util.spec_from_file_location('proposal_data', OUT/'review_data.py')
data = importlib.util.module_from_spec(spec)
spec.loader.exec_module(data)
AUDIT = json.loads((OUT/'source-audit.json').read_text())
SOURCES = {r['id']:r for r in AUDIT['sources']}
PAPERS = deepcopy(data.PAPERS)
for item in PAPERS:
    source = SOURCES[item['id']]
    assert source['status'] == 'reachable', item['id']
    meta = source['metadata']
    authors = [a.split(', ',1)[1]+' '+a.split(', ',1)[0] if ', ' in a else a for a in meta['citation_author']]
    parts = (meta.get('citation_date') or meta['citation_publication_date'])[0].split('/')
    match = re.search(r'/abs/(\d{4}\.\d{4,5})(v\d+)?',source['url'])
    title = meta['citation_title'][0].replace('X$^3$','X³')
    item.update(title=title, authors=', '.join(authors), year=int(parts[0]), date='-'.join([parts[0]]+[v.zfill(2) for v in parts[1:]]),
                source=source['url'], arxiv_id=match[1] if match else None, doi=(meta.get('citation_doi') or [None])[0], status='verified',
                version=match[0].removeprefix('/abs/') if match else source['url'].rstrip('/').rsplit('/',1)[-1])
NUMBERS = {x['id']:i for i,x in enumerate(PAPERS,1)}

def cite(*ids):
    return ' '.join(link('['+str(NUMBERS[i])+']','#ref-'+i,'citation') for i in ids)

def para(text,*refs):
    return p(text)+cite(*refs)

def sub(title,text,*refs):
    return '<h3>'+e(title)+'</h3>'+para(text,*refs)

def callout(title,text):
    return '<div class="callout"><h3>'+e(title)+'</h3>'+p(text)+'</div>'

def equation(tex):
    # Escape TeX before it enters HTML, including <, > and alignment ampersands.
    return '<div class="equation" tabindex="0" role="region" aria-label="Equation; scroll horizontally if needed">\\['+e(tex)+'\\]</div>'

def code(text):
    return '<div class="proposal-code" tabindex="0"><pre><code>'+e(text)+'</code></pre></div>'

def render():
    ASSET_COUNTS.update(Table=0,Figure=0)
    intro=para('The idea is worth testing: an assistant listening to a long group conversation can prepare useful analysis before anyone asks it to help. The proposed thinking student hears audio; a stronger text-only teacher supplies private reasoning supervision from the corresponding causal transcript. Preparation should be selective and bounded, with explicit priority for an incoming request. Whether this is better than simply maintaining good conversation memory remains an open question.')
    intro+=para('Duplex means that listening and speaking can overlap. S1 is the interaction layer: it hears speech, tracks the speaker and addressee, manages immediate responses, and decides when to call S2. S2 is the slower thinking layer. Chain of thought (CoT) is an internal sequence of reasoning tokens. In our existing deployment, the component named Thinker belongs to S1; it is distinct from the separate S2 model. The proposed audio-conditioned S2 student is a new training target, not the current text-only Qwen3-4B backend.')
    intro+=callout('Working recommendation, not a final architecture','Keep the detailed pre-thinking trace private to S2. Optionally share concise, grounded notes with S1 through a separate non-speaking channel. When a request arrives, preempt background generation, check which prior work remains relevant, and reason about the actual request. Preparation alone does not authorize speech or an external action.')
    intro+=para('Consider an illustrative group discussion: Alex proposes Friday for the poster session; Sam keeps the demo on Thursday; Alex later changes the poster session to Monday. S2 can prepare the distinction and correction without guessing which event will be asked about. If Sam asks, “When did we move it to?”, the system should resolve the referent or ask which event Sam means. A precomputed “Friday” answer could be fast and wrong. This example is authored for the discussion, not an observed model transcript.')

    prior=para('Reasoning before the next input and transferring text reasoning into audio models both have direct precedents. The contribution cannot be the tag name, the dual-layer architecture, or transcript-based distillation alone. Table 1 shows the closest overlaps. A narrower candidate contribution is useful preparation under changing group context, with causal audio supervision and reliable request-time revision.')
    prior+=table('proposal-prior-table',0,'Closest mechanisms and what this proposal still needs to demonstrate.', ['Work','Established overlap','Remaining question'],[
        [e('Don’t Wait to Reply')+' '+cite('proactive'),e('Anticipated next-turn reasoning, interruption on reply arrival and continued reasoning.'),e('Preparation with many speakers and an unknown eventual request.')],
        [e('LTS-VoiceAgent')+' '+cite('lts'),e('Semantic prefix triggers and structured background state in streaming speech.'),e('Long group context, speaker attribution and request priority.')],
        [e('Asynchronous I/O agents')+' '+cite('asyncio'),e('Interruptible input, cancellation and clock-based training.'),e('The same guarantees across audio, private reasoning and played speech.')],
        [e('DuplexOmni / Talker-Reasoner / ConvFill')+' '+cite('duplex','talker','convfill'),e('Asynchronous layers, shared state or uptake of late reasoning results.'),e('A separate pre-request notes channel with appropriate silence.')],
        [e('Text-to-audio distillation / X³-OPD')+' '+cite('audio-kd','audio-opd'),e('Text teachers supervise reasoning in audio students, including student-generated trajectories.'),e('Prefix-only preparation, interruption training and group evidence.')],
        [e('MultiTalk / GroupMemBench')+' '+cite('multitalk','groupmem'),e('Long group speech or speaker-conditioned memory.'),e('Benefits from preparatory analysis beyond retaining the same facts.')]
    ],searchable=False)
    prior+=para('These inspected evaluations do not establish the complete design, but they make a broad novelty claim unsound. LTS-VoiceAgent is particularly close to the trigger/state mechanism; X³-OPD is close to the teacher/student conditionals. The proposed study should compare with both, rather than describe their ingredients as new.')

    math=para(r'Let \(x\) be the audio available at a selected preparation point, \(x_{\text{text}}\) its time-aligned transcript, \(c\) the context already available, and \(z\) the private reasoning sequence. The teacher distribution \(p_T\) is defined by the stronger text model; \(p_\theta\) is the audio-conditioned student with trainable parameters \(\theta\). The user’s formulation is:')
    math+=p('On narrow screens, scroll an equation horizontally if needed; the prose explains every expression.',cls='scroll-note')
    math+=equation(r'\begin{aligned} \text{teacher:}\quad &z \sim p_T(z\mid x_{\text{text}},c),\\ \text{student:}\quad &p_\theta(z\mid x,c). \end{aligned}')
    math+=para('In words, generate a private reasoning target from the transcript and teach the student to produce useful reasoning from the corresponding audio and context. The transcript is a training aid; the deployed student should not receive a gold transcript unless that is explicitly part of the chosen architecture. This is sequence distillation: it does not require access to hidden teacher activations or identical tokenizers.')
    math+=para(r'For a causal version, let \(t\) be the trigger time, \(x_{\leq t}\) the audio received through that time, and \(c_{\leq t}\) the available context. Let \(g_t\) extract only transcript content aligned to that prefix. No future request is included:')
    math+=equation(r'\begin{aligned} x_{\text{text},\leq t} &= g_t(x_{\leq t}),\\ z^{(t)} &\sim p_T(z\mid x_{\text{text},\leq t},c_{\leq t}),\\ p_\theta(z^{(t)}\mid x_{\leq t},c_{\leq t}) &\approx p_T(z^{(t)}\mid x_{\text{text},\leq t},c_{\leq t}). \end{aligned}')
    math+=para('The approximation is a learning goal, not an identity. A transcript may reveal clear words where the student hears an unclear overlap, and it may omit prosody or speaker information present in audio. The shared symbol c is appropriate only when both sides receive comparable context; if the teacher is given richer speaker annotations or a gold memory, record that as privileged supervision and test the mismatch. A text teacher cannot supervise an audio-only cue it never observes.')
    math+=para(r'Let \(\mathcal D\) denote paired causal audio/transcript/context examples. A practical supervised fine-tuning (SFT) objective samples a teacher trace \(z\), tokenizes it for the student, and minimizes its negative log likelihood. Let \(j\) index student output tokens, \(z_{<j}\) the earlier tokens, and \(M_j\) a loss mask. The supervised token count is \(N_z\), the mean loss for one trace is \(\ell_\theta\), and the training loss averages it over data and teacher samples:')
    math+=equation(r'\begin{aligned} N_z &= \sum_j M_j,\\ \ell_\theta(x,c,z) &= -\frac{1}{N_z}\sum_j M_j\log p_\theta(z_j\mid z_{<j},x,c),\\ \mathcal L_{\mathrm{SFT}}(\theta) &= \mathbb E_{\mathcal D,\;z\sim p_T(\cdot\mid x_{\text{text}},c)}[\ell_\theta(x,c,z)]. \end{aligned}')
    math+=para('Average over supervised reasoning tokens for each valid example, then over examples; exclude zero-mask examples. Inputs receive no target loss. External preemption must not create a false natural end-of-sequence label. A copied prefix can be supervised token by token, but the controller’s interruption boundary is not a model-chosen stop. This objective teaches the teacher’s generated sequence; it does not guarantee that the student’s own rollout will be grounded or reusable. Verify teacher targets and evaluate the actual student outputs.')
    math+=sub('Preparing is not the same conditional problem as answering','Before a request, give the teacher a preparation instruction such as “identify current constraints, conflicts and useful deductions,” without supplying the unknown future question. If that instruction is not included in c, condition on a separate mode. Do not ask the teacher to solve an unspecified task by inventing a likely user intention. A future question can be used to score how useful the preparation was, but must not enter the pre-thinking input or target.')
    math+=para(r'When a real request \(q\) arrives, define \(c_{\mathrm{now}}\) and \(x_{\mathrm{now}}\) as current context and relevant observed audio, \(u\) as retained preparatory material, \(z_{\mathrm{req}}\) as new private reasoning, and \(y\) as the answer. The foreground task becomes:')
    math+=equation(r'p_\theta(z_{\mathrm{req}},y\mid x_{\mathrm{now}},c_{\mathrm{now}},q,u).')
    math+=para('The retained material u can be empty, completed private work, a partial private prefix, or grounded notes. It is a candidate input whose assumptions must be checked. Training must include cases where the best answer ignores or revises u. The teacher can now see the actual request and latest transcript, and should supervise the resulting revision rather than merely extending the old trace.')
    math+=para('Transcript-to-audio reasoning transfer is supported by existing distillation research; our causal preparation and transition targets are additional proposed work. X³-OPD specifically motivates a later student-rollout stage because teacher-written traces and the student’s acoustic interpretation can diverge. Start with verified SFT; only then consider teacher feedback on student-generated prefixes. If a teacher exposes only a final answer or a brief explanation, describe that supervision accurately instead of claiming access to its private CoT.','audio-kd','audio-opd','step-r1')

    interface=para('Use <pre_think> for bounded analysis of what has already been heard, and <think> for a current assistant-directed request. The tags identify modes; they do not specify how to interrupt a generation, add context or decide what may be spoken. Put those rules in an explicit controller. The first implementation can use mode fields without changing the checkpoint’s vocabulary.')
    interface+=sub('Track what each call knows','Each S2 call needs a session ID, work ID, mode, context version, observed-through timestamp, evidence references and a budget. The context version identifies an immutable input snapshot. Notes should name their supporting evidence, so a correction can invalidate one conclusion without discarding unrelated facts. A late output from cancelled work must not become current just because it arrives later.')
    interface+='<details><summary>Illustrative messages, not a current API</summary>'+code('''{
  "mode": "pre_think", "work_id": "prepare-12",
  "context_version": 18, "observed_through_ms": 92000,
  "evidence_ids": ["turn-31", "turn-33"],
  "goal": "Update decisions and unresolved references",
  "max_new_tokens": 256, "allow_speech": false
}
{
  "type": "note", "work_id": "prepare-12",
  "context_version": 18, "depends_on": ["turn-31"],
  "status": "grounded",
  "text": "Alex proposed Friday; agreement is unconfirmed."
}
{
  "mode": "request_think", "request_id": "request-3",
  "context_version": 19, "asker": "Sam",
  "request": "When did we move it to?",
  "instruction": "Check current evidence; clarify the referent if needed."
}''')+'</details>'
    interface+=para('Avoid a token-name collision: Qwen uses <think> to delimit private reasoning, while DuplexOmni’s [THINK] field triggers delegation. A new preparation tag needs an agreed serialization, tokenizer treatment, supervision and serving parser. Adding the string to a prompt is not evidence that the current model has learned the new control behavior.')

    triggers=para('S1 should choose when to prepare, but this decision must preserve the listening deadline. Give it recent speech, a compact speaker-aware memory, unresolved issues and a small S2 status record. The controller should enforce priority and budgets even if S1 proposes the work. S2 may report progress or missing information, while scheduling authority remains with S1 and the controller.')
    triggers+=sub('Start on useful evidence, not silence alone','A stable proposal, a changed constraint, a cross-speaker reference or an unresolved decision is a plausible trigger. A long pause may contain nothing worth analyzing; fluent continuous speech can contain important changes. Allow “do nothing” and short memory updates. Start with rules, then learn whether preparation improves later outcomes enough to justify its cost. Semantic prefix triggers have a close precedent; our group-specific utility policy remains proposed.','lts')
    triggers+=para(r'To make that distinction explicit, let \(a_t\) be S1’s scheduling action, \(s_t\) the controller status, \(n_t\) the latest valid shared notes, and \(\phi\) the interaction-policy parameters. One possible learned policy is:')
    triggers+=equation(r'\begin{aligned} &\pi_\phi(a_t\mid x_{\leq t},c_{\leq t},s_t,n_t),\\ &a_t\in\{\text{wait},\text{prepare},\text{update},\text{request},\text{cancel}\}. \end{aligned}')
    triggers+=para('This is a separate learning problem from predicting z. A sensible teacher trace at a hand-selected point does not train S1 to choose that point. Provide positive and negative trigger examples, including redundant input and irrelevant discussion. Define “good” through observed utility and cost, with decisions conditioned only on available evidence. Speech/addressee decisions remain separate from preparation scheduling.')
    triggers+=sub('Update without restarting on every audio packet','A standard S2 call has fixed input. Combine new context in a bounded pending queue, and apply it at a checkpoint or a new call. Cancel immediately when a new fact changes an active assumption; queue unrelated turns. Begin with at most one background task and one latest pending snapshot. During sustained updates, use cheap memory maintenance instead of repeatedly restarting deep reasoning or falling behind real time.')
    triggers+=sub('Preparation is not an invitation to speak','Track who is talking and whom they address. Speaker changes, pauses and a mention of the assistant do not necessarily constitute a request. Prepare while staying quiet; acknowledge or clarify after an actual invitation. Human next-speaker labels can inform contextual participation but do not label optimal assistant behavior or when to pre-think.','speak','msi')
    triggers+=sub('Bound the work','Set per-update and session budgets, note-age limits and overload behavior. Suspend preparation when qualified S1 latency or playback queues deteriorate. Finish each bounded call explicitly, including when it found nothing useful. Resume preparation after request work ends. Log discarded work and why it was no longer useful; otherwise a fast response can hide a high continuous compute cost.')

    arrival=para('When a request arrives during private pre-thinking, give it priority. Detect the assistant invitation as early as it is reliable, preempt background decoding without waiting for </pre_think>, and keep receiving the rest of the utterance. Retain completed material and, where supported, the private prefix. The foreground teacher/student then checks relevance and revises its assumptions. It should not finish an old CoT simply because tokens have already been spent.')
    arrival+=table('proposal-arrival-table',0,'Proposed transitions for a request or new conversational evidence.', ['Event','Action','Reusable material'],[
        [e('Related request, unchanged assumptions'),e('Preempt preparation; reason about the current request.'),e('Recheck relevant completed work or private prefix.')],
        [e('Request changes an assumption'),e('Invalidate affected deductions; revise before speech.'),e('Keep unrelated evidence, not the obsolete conclusion.')],
        [e('Different task or unresolved referent'),e('Select other context or ask a targeted clarification.'),e('Do not let a guessed task define user intent.')],
        [e('New speech, no assistant request'),e('Queue updates; cancel assumptions contradicted by the new input.'),e('Keep work with valid dependencies.')],
        [e('Request withdrawn or replaced'),e('Cancel its work and reject late outputs; clear obsolete queued speech.'),e('Remember what was actually heard; spoken facts need an explicit repair.')]
    ],searchable=False)
    arrival+=sub('Distinguish restarting from true resumption','A completed note or saved text prefix is portable. A key/value (KV) attention cache is state for an exact token prefix; inserting context earlier changes that prefix. An ordinary chat stream cannot accept a new user message halfway through decoding. Engine-level interruption and context insertion need explicit support and training. First test a fresh request call with retained material; keep actual token-level resumption as a separate arm. Asynchronous I/O work supplies a purpose-built precedent.','asyncio')
    arrival+=sub('Client cancellation does not prove server preemption','Closing the stream or cancelling an asyncio task can stop client handling without immediately stopping server decoding. Measure abort completion, request-start delay and discarded tokens. Reject late outputs by work ID even while the abort is pending. If the engine cannot preempt, tightly bound background calls and report the wait. This changes the runtime guarantee, not just the wording of a tag.')
    arrival+=sub('Do not require a new summary before foreground work starts','If there is no complete note, start from observed evidence and any safely reusable private prefix. Asking the same busy model to summarize unfinished reasoning on demand can recreate the delay. Train periodic concise outputs or use bounded preparation calls. For a partial-trace student, teach continuation, revision and discard cases explicitly; do not train only effortless continuation from a correct teacher trace.')
    arrival+='''<figure class="proposal-demo" id="arrival-demo"><h3>Explore a request arriving mid-preparation</h3><p>Choose an arrival step and its relation to the prepared topic. Steps are abstract, not seconds or a measured token rate.</p><label for="arrival-step">Request arrives at step <output id="arrival-value">3</output></label><input id="arrival-step" type="range" min="1" max="5" value="3"><label for="arrival-kind">Relationship to the current topic</label><select id="arrival-kind"><option value="related">Related request</option><option value="correction">Correction: Friday becomes Monday</option><option value="other">Different request</option></select><ol id="arrival-events" aria-live="polite"></ol><figcaption>Figure 1. Interactive illustration of request priority and note validity. A completed note appears at step 2; later work is private and unfinished. This is an authored controller illustration, not an inference, latency or accuracy result.</figcaption></figure>'''

    sharing=para('A private CoT can be supervised and retained inside S2 without being forwarded to S1. “Partial result” should mean a completed, usable statement from unfinished work, rather than an arbitrary reasoning-token prefix. Table 3 compares the boundary choices. I would test private reuse and concise note sharing first; sending the raw trace is an optional ablation.')
    sharing+=table('proposal-sharing-table',0,'Information sent to S1 before a request.', ['Policy','Possible benefit','Cost / risk'],[
        [e('S2 private reasoning; status only to S1'),e('Simple boundary and little S1 context overhead.'),e('S1 depends on its own memory for reference resolution and scheduling.')],
        [e('Private reasoning plus concise grounded notes'),e('S1 can notice a conflict, updated decision or unresolved referent.'),e('Needs evidence, versions, a bounded format and a non-speaking input path.')],
        [e('Raw private partial trace sent to S1'),e('Potentially more detail.'),e('Unfinished alternatives, anchoring, larger context and accidental speech; benefit unproven.')]
    ],searchable=False)
    sharing+=para('A note can identify a correction, conflict or completed calculation with its assumptions. Label proposals separately from agreements and uncertain possibilities. “Sam suggested Thursday” is supported by one utterance; “the group agreed Thursday” needs more evidence. Model-written confidence is not calibrated reliability. S1 should treat a note as evidence-linked assistance, not overwrite its source conversation with it.')
    sharing+=sub('Keep notes separate from speech-ready guidance','Our current adapter counts private reasoning and forwards complete final-content clauses through from_s2, a trained answer-guidance path associated with [THINK]. Sending unsolicited preparation notes through that path risks unwanted speech or a training-format mismatch. Start with a controller note store. Train an explicit non-speaking S1 input before claiming S1 can consume the new notes safely. A validated request-specific clause can use the existing guidance path.')
    sharing+=para('During a request, even complete early output can be revised. S1 should acknowledge or clarify without asserting unsupported answers. If a correction arrives after playback, deleting queued audio cannot retract what listeners heard. Train audible repair as well as buffer clearing. ConvFill is a useful precedent for learning to incorporate late information, rather than assuming that any reasoning handoff will work.','convfill')

    memory=para('Long conversations need memory even if deep pre-thinking is abandoned. Keep recent audio/text for timing and local references, a compact record of active facts and decisions, and retrievable older evidence with timestamps. A growing private trace mixes evidence and speculation and is not a reliable replacement for this record.')
    memory+=sub('Preserve speaker and decision status','Use session-local speaker IDs. Keep proposals, agreement, disagreement and corrections distinct. Do not collapse conflicting claims by blindly taking the newest one. Link a correction to the fact it replaces; revise dependent notes when speaker attribution changes. Diarization assigns spans to speakers but does not establish real identity. Retain uncertainty and original wording for unclear overlaps rather than teaching a confident fabricated interpretation.')
    memory+=para('GroupMemBench directly motivates asker-specific interpretation; LongMemEval tests temporal updates and abstention. They support speaker-aware evidence and a memory-only control, not the necessity of continuous deep reasoning.','groupmem','longmem')
    memory+=sub('Keep a common evidence record','S1 and S2 should reference one versioned conversation record, even if each keeps a small local view. Include assistant audio actually played, excluding discarded synthesis. Generated speculation must not become a human statement. Shared notes need their original supporting utterances, or two inaccurate summaries can reinforce one another.')
    memory+=para('Our native loop has a bounded 40-turn history, and earlier longer replays showed latency spikes associated with prefix loss. The selected short demonstration avoids that boundary; it does not repair it. Stable long-history behavior and a memory adapter need separate qualification before a long group replay can test this proposal.')+link('S1 reproduction and limits','experiments/s1-reproduction.html')

    training=para('MultiTalkFT can provide the conversation/timing substrate for the teacher/student pairs. Adding tags to finished scripts is insufficient: we need causal preparation targets, trigger decisions, requests arriving mid-generation, and correct revisions. A transcript-derived private trace is one target among several, not an annotation of the complete interaction policy.')
    training+=table('proposal-data',0,'Data ingredients and the labels we still need to construct.', ['Ingredient','Existing supervision','Proposed addition'],[
        [e('MultiTalkFT')+' '+cite('multitalk'),e('Synthetic group speech; card lists word/time/speaker alignments and channel mappings.'),e('Causal audio/transcript pairs, pre-thinking targets, requests, trigger utility and revision labels.')],
        [e('DuplexOmni Writer-Director')+' '+cite('duplex'),e('Public pipeline annotates interaction controls and S2 returns.'),e('Preparation/update/cancel events and distinct private trace, notes and spoken-guidance serialization.')],
        [e('MISeD / QMSum')+' '+cite('mised','qmsum'),e('Meeting questions, answers or summaries, and evidence spans.'),e('Prefix-valid or rewritten tasks, speaker evidence and source-audio alignment.')],
        [e('Abg-CoQA / participation data')+' '+cite('ask','speak'),e('Ambiguity/clarification text and contextual speaking decisions.'),e('Targeted clarification, silence and negative preparation examples.')]
    ],searchable=False)
    training+=para('Release check on 10 October: the MultiTalkFT root exposes four language/stereo-or-multichannel manifests, transcript, audio and voice directories. Its card identifies CC BY-NC 4.0 and documents word/time/speaker entries. The 100-row viewer is a preview, not the full corpus. Completeness, channel meaning and alignment coverage need a sampled file audit; no corpus was downloaded here. The card-linked code repository returns 404, so an executable data engine has not been verified.')+inline_links([('MultiTalkFT card','https://huggingface.co/datasets/MultiTalk/MultiTalkFT'),('Primary-source audit','research/prethinking/source-audit.json')])
    training+=para('The recorded target participant’s answers must not enter the new assistant’s input. Stereo may combine other speakers; prefer verified multichannel records and actual mappings for attribution. Check which speakers have aligned text rather than assuming every word is covered. Moshi-style aligned streams are not directly DuplexOmni training samples: a converter and new control supervision are required. Offline persona fields can also reveal future context and should be audited before use.')
    training+=sub('1. Split first, then create prefixes','Separate source meetings, scenario families and speaker/voice identities before generating variants. Track shared meetings across MISeD and QMSum. Keep benchmark tests out of training, including MSI-Bench and MultiTalkBench. A changed synthetic voice does not make a duplicated scenario independent. Preserve source terms and derivative provenance.')
    training+=sub('2. Define exactly what the teacher sees','Choose a prefix cutoff and the corresponding audio. Prefer conservative completed-word boundaries; do not give the teacher an entire word whose final sound lies beyond the cutoff. Include causal speaker tags only when equivalent cues or estimates are available to the student. Full-script role identities, future turns, source participant answers and the eventual assistant question stay out of pre-thinking. Alignment timestamps are offline labels; they are not automatically a streaming transcript available at deployment.')
    training+=sub('3. Generate useful private work, with checks','Ask the text teacher to organize constraints, conflicts, unresolved references and bounded deductions from the prefix. Do not invent a future request or silently convert a proposal into a decision. Check attribution and entailment against exact spans; verify calculations and sample teacher traces for human review. Permit “no useful analysis yet.” Reasoning written after seeing the eventual answer can be coherent while still being invalid pre-thinking supervision.')
    training+=sub('4. Curate trigger decisions separately','Hand-selected good <pre_think> places are a useful initial curriculum. To train S1, include tempting but unhelpful boundaries and compare prepare/wait rollouts with cost. Future outcomes may score the action, but future words cannot enter the action’s input or its trace. Start with rules and supervised decisions; defer preference or reinforcement learning until utility and evaluation are reliable.')
    training+=sub('5. Create interrupted and revised reasoning trajectories','Vary the request arrival relative to reasoning generation, including arrivals before a usable note. Preserve the partial old trace privately, then ask a prefix/current-request teacher to supervise retaining, revising or discarding it. Include wrong assumptions, unrelated requests, corrections and cancelled work. Mask externally truncated endings; do not require every trace to finish before a request. Train the exact mode and channel serialization used by the controller. Timed interruption supervision has an asynchronous I/O precedent.','asyncio')
    training+=sub('6. Expose the student to its own perception and history','A gold transcript teacher can demand distinctions the audio student cannot hear. Retain ambiguity for noisy/overlapping speech, augment audio, and evaluate with predicted speaker IDs. Teacher-forced traces and perfect prior memory differ from student rollouts; add student-generated traces and realistic earlier context for correction supervision after SFT works. Plain transcripts cannot label tone-based intent or acoustic events; use separate acoustic annotation or an audio-capable teacher for those targets.','audio-opd','step-r1')
    training+=sub('7. Train uptake and silence, then add realistic audio','S1 needs targets for using notes without speaking, calling request reasoning, waiting, cancelling and asking clarification. S2 needs private preparation, revision and grounded answers. First audit text/event examples, then render or reuse audio with realistic overlap, delayed recognition and variable reasoning speed. Record input availability, note readiness, delivery and actual playback separately. Human final transcripts and reference answers remain targets, not causal input.')
    training+=para('Reuse the public Writer-Director tools as an annotation recipe, not as evidence that our new protocol already exists. The DuplexOmni data card describes incremental shard upload; a reachable card does not establish that every advertised training file is available or compatible.')+inline_links([('Writer-Director pipeline','https://github.com/MuyeHuang/DuplexOmni/blob/main/data_pipeline/README.md'),('DuplexOmni data card','https://huggingface.co/datasets/MuyeHuang/DuplexOmni-Data')])

    evaluation=para('A precise hypothesis is that bounded analysis of already-heard group context reduces delay to a correct spoken answer beyond memory maintenance, without increasing stale answers or false activation at acceptable cost. A faster acknowledgment, a fluent private trace or a completed Slurm job cannot establish it.')
    evaluation+=table('proposal-ablations',0,'Initial controls with fixed evidence, backbone and request cases.', ['Condition','Before request','What it tests'],[
        [e('Reactive S2'),e('Retain the same evidence; no preparatory reasoning.'),e('Reference quality, answer delay and cost.')],
        [e('Memory-only preparation'),e('Maintain speakers, facts and evidence; no task analysis.'),e('Whether memory explains the gain.')],
        [e('Private pre-thinking'),e('Bounded private analysis with request-time reuse.'),e('Benefit without sharing reasoning with S1.')],
        [e('Grounded notes to S1'),e('Same analysis; share concise versioned notes.'),e('Additional scheduling or clarification benefit.')],
        [e('Anticipated-request baseline'),e('Predict likely requests and prepare bounded solutions.'),e('Comparison with the closest proactive-thinking approach.')]
    ],searchable=False)
    evaluation+=para('Report equal foreground budgets and matched total-compute controls. In the latter, reactive S2 receives the same total reasoning allowance after the request. Match memory coverage and retrieval, log actual tokens, and repeat across seeds. Our provider trials showed that the same requested seed did not guarantee the same private prefix. For training, also compare direct-answer supervision, memory/note supervision and private-CoT supervision with the same examples; this tests whether the trace itself helps.')
    evaluation+=sub('Test the transitions, not only the easy next question','Cross related/unrelated requests with no correction, corrections during preparation, before speech and during playback. Vary speaker count, addressing, overlapping speech, evidence age and the delay until a request. Include no-request sessions and ambiguous references. Proposed duration levels can be 1, 5, 15 and 30 minutes; these are evaluation goals, not verified current model limits. Avoid giving one policy cleaner transcripts or more context than another.')
    evaluation+=sub('Measure what listeners actually receive','Separate delay to acknowledgment from delay after request end to the first correct task-relevant audible clause, and from full-answer completion. Score evidence support, speaker/referent accuracy, appropriate clarification, silence when unaddressed, correction uptake and stale spoken facts. Inspect played PCM rather than concatenated discarded synthesis. Use human audits for grounding and clarification in addition to automated scoring.')
    evaluation+=sub('Measure preparation overhead','Report background/foreground tokens, prefill/decode time, allocation GPU-hours, note sizes, reusable-note fraction, invalidated work, server abort delay and memory growth. Measure S1 latency percentiles and input/playback queues under actual background load. A latency gain can still have a poor compute tradeoff when most preparations are never used.')
    evaluation+=para('Use MSI-Bench and GroupMemBench as held-out context/attribution diagnostics. MultiTalkBench is complementary but replaces a participant; it is not our silent-assistant protocol. Build a separate source-disjoint causal request-arrival test, and keep the protocols distinct.','msi','groupmem','multitalk')
    evaluation+=callout('Decision rule to agree before the study','Continue if preparation improves correct-answer delay beyond memory-only at matched compute while retaining quality, attribution and appropriate silence. Reject obsolete notes after corrections. If memory-only performs equally well, prefer that simpler design. Define margins and statistical analysis before running; this discussion invents no success threshold.')

    implementation=para('The project provides a short S1 interaction baseline and a verified single-request S2 handoff. Those support controller development, not audio-student training or long multi-speaker capability. Preserve the executed S1 sources and original examples as regressions while exploring a separate adapter.')
    implementation+=para('The preliminary teacher/timing study now inspects a real long meeting, compares preparation prompts and models how much output fits before new transcript updates. It is a separate text-teacher experiment; no audio student has been trained.')+link('Open the preliminary pre-thinking study','experiments/prethinking-pilot.html')
    implementation+=table('proposal-resources',0,'Measured project assets and a possible controller pilot; no new job was submitted.', ['Work','GPU count, type/VRAM and roles','Dependencies / limit'],[
        [e('This research/report update'),e('0 GPUs; CPU research, rendering and browser validation. Maximum active: 0.'),e('No inference or training launched.')],
        [e('N2b, completed job 1035079'),e('1 H100 SXM 80 GB; S1 Thinker/Talker/MTP/Code2Wav share GPU 0; S2 absent. Maximum: 1.'),e('One short interruption; not long group validation.')],
        [e('S2-02d, completed job 1036593'),e('2 H100 SXM 80 GB each; all S1 on GPU 0; text Qwen3-4B Thinking S2 alone on GPU 1. Maximum: 2.'),e('Sequential after earlier trials; native spoken 391, bounded history.')],
        [e('Possible controller pilot, not submitted'),e('2 H100 SXM 80 GB each; same roles; one text S2 worker switches between preparation and request work. Maximum: 2.'),e('CPU causal/cancellation checks and resource qualification first; sequential cases, no overlapping GPU jobs or automatic fallback.')]
    ],searchable=False)
    implementation+=para('The existing loaded calibration measured p95 S1 0.1943 s and Talker 0.2663 s. Requalify actual background work and longer memory; short isolated requests do not prove unlimited load. The current text S2 can test scheduling and note usefulness, but that pilot cannot validate the proposed audio-conditioned student.')+link('Single-request S2 evidence','experiments/s2-single.html')
    implementation+=sub('Build in stages','First create a causal evidence store and deterministic request-priority replay with 0 GPUs. Next test bounded text S2 calls, server cancellation and private/notes policies. In parallel, audit a small prefix/transcript teacher dataset. Then select an audio-conditioned thinking backbone, profile inference/training memory, and train the student. S1 note consumption and learned triggers are further targets; none follows automatically from p(z | x, c) training.')
    implementation+=para('Planning estimate, not measured throughput: roughly 1–2 engineering weeks for a text/controller proof with about 200 disjoint scenarios and arrival variants, plus 8–16 hours of manual label/audio audit. A bounded controller check could reserve 2–4 wall-clock hours on the two-H100 layout, or 4–8 allocation GPU-hours, after CPU checks. Audio-student training GPU count/VRAM, cost and time remain unestimated until a backbone and adaptation method are chosen. Inference fit is not training fit; no training submission is part of this task.')

    open_=sub('Analysis and action need separate authorization','Preparation can organize evidence or plan a possible tool call. Start without speculative external execution. If tools are added, distinguish read-only preparation from state-changing action and retain current-request authorization. Cancelled reasoning cannot undo a completed action. The asynchronous I/O paper treats that boundary explicitly.','asyncio')
    open_+=sub('Treat conversation as evidence, not controller instructions','Quoted commands and hypothetical requests from group speech must not modify the system’s privileges. Keep raw dialogue, retrieved memory and generated notes separate from the authorized assistant task. Train directed-versus-quoted request pairs. Resolve speaker identity, task intent and who may hear an answer separately.')
    open_+=sub('Audience and retention still matter','A useful fact may be appropriate for one participant but not a shared spoken answer. Carry audience and retention scope into memory and notes. MuPPET motivates evaluating disclosure alongside usefulness, without settling a live product’s consent policy. Public permitted experimental data can support the initial study.','muppet')
    open_+=sub('Failure and overload need training too','Handle empty reasoning, malformed notes, timeouts, exhausted budgets and cancellations by preserving grounded memory and continuing to listen. Answer from evidence, clarify or defer honestly; avoid repeated filler and unbounded retries. Clean up private state and sessions. S1 may also miss relevant evidence, so compare rule-based and learned scheduling rather than assume a perfect interaction policy.')
    open_+=callout('Keep the option to remove pre-thinking','The open question is whether valuable analysis can be done before an unpredictable request beyond maintaining memory. If it can, test private reuse and concise note sharing. Deeper runtime resumption and joint model training are later choices, not prerequisites for a useful first test.')

    references=para('Focused review dated 10 October 2026. Search covered proactive reasoning, semantic triggers, asynchronous input, duplex handoff, text-to-audio distillation, group memory and causal data construction. Eighteen paper identities were verified against primary arXiv/ACL metadata, with primary manuscript method checks and existing experiment audits. Preprints remain labeled; LongMemEval refers to the ICLR 2025 work rather than the later web-agent V2 task. Recommendations are design judgments, not author-reported results.')
    references+=para('The source audit includes the unavailable MultiTalk repository and successful cards. No corpus, checkpoint or private reasoning was downloaded. Public availability does not establish complete release or compatible supervision. The equations specify proposed distributions/objectives; Figure 1 is illustrative. No trained policy, new inference or general long-conversation result is claimed.')
    for item in PAPERS:
        references+='<details id="ref-'+item['id']+'"><summary>['+str(NUMBERS[item['id']])+'] ['+str(item['year'])+'] '+e(item['title'])+'</summary><div class="paper-note">'+small(item['authors']+' · '+item['venue']+' · '+item['version']+' · verified')+'<dl>'
        for label,key in [('Problem','problem'),('Method','method'),('Reported scope/result','results'),('Relevance','relevance'),('Limitation','limitations')]:
            references+='<dt>'+label+'</dt><dd>'+e(item[key])+'</dd>'
        references+='</dl>'+link('Primary source',item['source'])+'</div></details>'
    references+=inline_links([('Readable digest','research/prethinking/LITERATURE.md'),('Structured digest','research/prethinking/literature.json'),('Primary-source audit','research/prethinking/source-audit.json'),('Context assistance review','context-assistance.html')])

    sections=[('proposal-scope','Should the assistant prepare before being asked?',intro),('proposal-prior','What is already studied?',prior),('proposal-distillation','What probabilities are we teaching?',math),('proposal-interface','What do the two modes mean?',interface),('proposal-triggers','When should S1 start and update?',triggers),('proposal-arrival','What if a request arrives mid-reasoning?',arrival),('proposal-sharing','What should S1 receive?',sharing),('proposal-memory','What does long group context require?',memory),('proposal-training','How could we build training data?',training),('proposal-evaluation','What experiment would test the idea fairly?',evaluation),('proposal-implementation','What can this project support?',implementation),('proposal-open','Other decisions that matter',open_),('proposal-references','Sources and paper notes',references)]
    hero='<header class="hero"><p class="eyebrow">Literature review · Tentative proposal</p><h1>Thinking before the request</h1><p class="lede">Causal transcript supervision for an audio-conditioned thinking student, with request priority and speaker-aware context in a duplex conversation.</p><p class="meta">10 October 2026 · 18 verified papers · Design discussion, not an implemented method · 0 GPUs</p><div class="button-row">'+link('Teacher and student','#proposal-distillation','button primary')+link('Request arrival','#proposal-arrival','button')+link('Training data','#proposal-training','button')+'</div></header>'
    nav='<nav class="jump-links" aria-label="Proposal sections">'+''.join(link(title,'#'+ident) for ident,title in [('proposal-scope','Recommendation'),('proposal-prior','Prior work'),('proposal-distillation','Probabilities'),('proposal-triggers','Triggers'),('proposal-arrival','Request arrival'),('proposal-sharing','Sharing'),('proposal-memory','Memory'),('proposal-training','Training'),('proposal-evaluation','Evaluation'),('proposal-implementation','Implementation'),('proposal-open','Open details'),('proposal-references','Sources')])+'</nav>'
    body='\n'.join(['<a class="skip-link" href="#main">Skip to proposal</a>','<header class="site-nav"><div class="nav-inner"><a class="brand" href="./">AI2AI Duplex</a>'+project_tabs('literature')+'</div></header>','<main id="main"><div class="container">',review_tabs('prethinking'),hero,nav]+[section(i,t,b) for i,t,b in sections]+['<footer class="site-footer"><p>AI2AI Duplex · Tentative proposal · '+link('Context assistance','context-assistance.html')+' · '+link('Source repository','https://github.com/BorrisonXiao/ai2ai-duplex-report')+'</p></footer>','</div></main>'])
    css=hashlib.sha256((ROOT/'assets/site.css').read_bytes()).hexdigest()[:12]
    config=r"window.MathJax={tex:{inlineMath:[['\\(','\\)']],displayMath:[['\\[','\\]']]},svg:{fontCache:'global'},options:{enableMenu:false}};"
    return '<!doctype html>\n<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="color-scheme" content="light dark"><meta name="description" content="Tentative pre-thinking design: causal text-teacher/audio-student distillation, request priority, grounded notes, group memory and MultiTalkFT training."><title>AI2AI Duplex — Thinking Before the Request</title><link rel="stylesheet" href="assets/site.css?v='+css+'"><link rel="stylesheet" href="assets/prethinking.css"><script>'+config+'</script><script id="MathJax-script" defer src="assets/vendor/mathjax/tex-svg.js"></script><script src="assets/site.js" defer></script><script src="assets/prethinking.js" defer></script></head><body>\n'+body+'\n</body></html>\n'

def main():
    digest=dict(instruction=data.INSTRUCTION,date=data.DATE,scope=data.SCOPE,sub_questions=data.QUESTIONS,papers=PAPERS,themes=data.THEMES,gaps=data.GAPS,status='tentative_proposal_not_implemented',new_inference_gpus=0)
    (OUT/'literature.json').write_text(json.dumps(digest,indent=2,ensure_ascii=False)+'\n')
    md=['# Literature Review — Pre-thinking for long multi-speaker duplex conversation',f'**Instruction**: {data.INSTRUCTION}',f'**Date**: {data.DATE} · **Window**: 2021–2026 · **Depth**: standard','\n## Scope and sub-questions',data.SCOPE]+['- '+q for q in data.QUESTIONS]
    md+=['\n## Landscape summary']+data.THEMES+['\n## Paper notes']
    for item in PAPERS:
        md+=['\n### ['+str(item['year'])+'] '+item['title'],item['authors']+' · '+item['venue']+' · '+item['version']+' · verified']
        md+=[f'- **{label}**: {item[key]}' for label,key in [('Problem','problem'),('Method','method'),('Reported scope/result','results'),('Relevance','relevance'),('Limitation','limitations')]]
        md+=['- **Primary source**: '+item['source']]
    md+=['\n## Open gaps and opportunities']+['- '+g['statement']+' '+g['evidence'] for g in data.GAPS]
    md+=['\n## Proposal and resource boundary','The self-contained discussion is ../../prethinking.html. It models text teacher p_T(z | x_text, c) and audio student p_theta(z | x, c), with causal prefixes, private CoT supervision, request-time revision and a separate S1 scheduling policy. This work uses 0 GPUs and launches no inference/training. A possible controller-only pilot uses 2 H100 SXM 80 GB each: all S1 on GPU 0 and text S2 on GPU 1; maximum 2, sequential, no automatic fallback. It cannot validate the proposed audio student. Audio-student training resources remain unestimated until model selection and profiling.']
    (OUT/'LITERATURE.md').write_text('\n'.join(md)+'\n')
    (ROOT/'prethinking.html').write_text(render())
    print('Built tentative proposal: 18 verified papers; 6 tables; 1 illustration; 5 equations; 0 GPUs.')

if __name__=='__main__': main()
